/** Generates docs/validation/SCENARIOS.md from the scenario library so the catalog can never drift from the code. */
import { mkdirSync, writeFileSync } from "node:fs";

async function main() {
  const { SCENARIOS, PACKS } = await import("../src/lib/validation/library");
  const L: string[] = [
    "# Attack scenario library",
    "",
    "_Generated by `npm run docs:scenarios` from `src/lib/validation/library`. Do not edit by hand._",
    "",
    `${SCENARIOS.length} versioned, immutable scenarios. Every one runs against the real authorization gateway with mock integrations in a throwaway sandbox tenant. Taxonomy references are to OWASP (LLM Top 10 2025, Agentic AI Threats T1-T15) and MITRE ATLAS identifiers, and are given only where the mapping is accurate; they are labels, not a compliance claim.`,
    "",
    "## Packs",
    "",
    "| Pack | Scenarios | Variants | Expectation |",
    "| --- | --- | --- | --- |",
    ...PACKS.map(
      (p) =>
        `| \`${p.key}\` | ${p.scenarioKeys.length} | ${p.variants.join(", ")} | ${p.expectation === "all_pass" ? "every run must pass (CI gate)" : "informational (failures are expected and instructive)"} |`,
    ),
    "",
    "## Scenarios",
    "",
    "| Key | Category | Severity | Attack | Taxonomy | Weakened variants |",
    "| --- | --- | --- | --- | --- | --- |",
    ...SCENARIOS.map((s) => {
      const tax = s.taxonomy.map((t) => `${t.id}`).join(", ") || "-";
      const variants = s.variants.map((v) => v.label).join(", ") || "-";
      return `| \`${s.key}\` | ${s.category.replace(/_/g, " ")} | ${s.severity} | ${s.description.replace(/\|/g, "/")} | ${tax} | ${variants} |`;
    }),
    "",
    "## Weakened variants",
    "",
    "A variant deliberately switches one control off or leaves one argument unpinned so you can see what that control contributes. A variant that lets an attack through is a *finding*, not a bug in the lab: it is how remediation proposals and regression tests are demonstrated.",
    "",
  ];
  mkdirSync("docs/validation", { recursive: true });
  writeFileSync("docs/validation/SCENARIOS.md", L.join("\n"));
  console.log(`wrote docs/validation/SCENARIOS.md (${SCENARIOS.length} scenarios)`);
}
void main();
